let state={started:false,name:'Drift Island',round:0,stats:[65,60,60,60],player:{x:420,y:650},color:'#ffbd69',collected:[],log:[],flags:{water:0,rules:0,shelter:0,guard:0,union:0,state:0,power:'Unclaimed'},failures:[],pending:null,finished:false,knowledge:0,law:'Shared food must stay in the covered camp store.',builds:[],activity:{}};
try{const old=JSON.parse(localStorage.getItem(KEY));if(old&&old.version===1){const {version,...data}=old;state={...state,...data};}}catch{}
const labels=['Supplies','Safety','Trust','Freedom'], colors=['#e1ba77','#8dc4cc','#90ccb0','#c5a7de'];
let target=null,keys={},sound=false,actx=null,toastTimeout,choiceLocked=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,version:1}));$('#saved').textContent='Saved on this device';}catch{$('#saved').textContent='Saving unavailable in this browser';}}
function beep(freq=400,duration=.09){if(!sound)return;try{actx??=new(window.AudioContext||window.webkitAudioContext)();const o=actx.createOscillator(),g=actx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.04,actx.currentTime);g.gain.exponentialRampToValueAtTime(.001,actx.currentTime+duration);o.connect(g);g.connect(actx.destination);o.start();o.stop(actx.currentTime+duration);}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function clamp(n){return Math.max(0,Math.min(100,n))}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function apply(delta){const before=[...state.stats];state.stats=state.stats.map((n,i)=>clamp(n+delta[i]));state.stats.forEach((n,i)=>{if(n===0&&!state.failures.includes(i))state.failures.push(i)});return state.stats.map((n,i)=>n-before[i])}
function baseRender(){
$('#islandName').textContent=state.name;const m=missions[Math.min(state.round,15)];$('#roundLabel').textContent=state.finished?'DAY 16 / 16 · COMPLETE':`DAY ${String(state.round+1).padStart(2,'0')} / 16`;
$('#missionTitle').textContent=state.finished?'Your island’s story':m.title;$('#missionGoal').textContent=state.finished?'Explore your island or read your final report.':m.goal;$('#objective').textContent=state.finished?'All missions resolved':`Destination: ${locations[m.loc].name}`;$('#travel').innerHTML=state.finished?'View final report <span>↗</span>':'Go to mission <span>↗</span>';
$('#meters').innerHTML=state.stats.map((n,i)=>`<div class="meter ${n<=25?'low':''}" style="--c:${n<=25?'#ee9b83':colors[i]}"><div class="meter-head"><span>${labels[i]}</span><strong>${n}<small style="font-size:8px;color:#7c9c9a"> /100</small></strong></div><div class="meter-track" role="meter" aria-label="${labels[i]}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${n}"><div class="meter-fill" style="width:${n}%"></div></div></div>`).join('');
$('#progressBar').style.width=(state.round/16*100)+'%';$('#progressText').textContent=`${state.round} of 16 missions resolved`;$('#cacheCount').textContent=`${state.collected.length} / 12 caches collected`;$('#logCount').textContent=state.log.length;$('#weather').textContent=(state.round===9||state.round===10)?'• Storm front':'• Clear skies';
$('#waterTag').textContent=`Water • ${['Unmanaged','Rationed','Repaired'][state.flags.water]}`;$('#rulesTag').textContent=`Rules • ${state.flags.rules?'In place':'None'}`;$('#powerTag').textContent=`Power • ${state.flags.power}`;
const low=Math.min(...state.stats);$('#campCondition').textContent=state.failures.length?'Camp in crisis':low<=25?'Under pressure':low>=60?'Holding together':'A fragile balance';$('#campDetail').textContent=state.failures.length?state.failures.map(i=>['Emergency rationing.','Guard post abandoned.','Camp has split.','Ren controls camp.'][i]).join(' '):low<=25?'One part of camp is close to breaking.':'Your next decision can change the balance.';
const last=state.log.at(-1);$('#radio').innerHTML=[['Jo','#a3c5a3',state.stats[0]<=25?'Stores are low. Find a supply cache.':state.flags.water===2?'Water is running again. Keep it that way.':'Supplies don’t organize themselves.'],['Ash','#b9a4d3',state.stats[3]<=25?'We need a voice in this camp.':state.flags.union?'Two camps working together. Finally.':'A rule needs a reason.'],['Ren','#d7a272',state.flags.power.includes('Ren')?'Order first. Questions later.':last?'Let’s see if your plan holds.':'Someone has to take charge.']].map(([n,c,t])=>`<div class="message"><div class="portrait" style="--c:${c}"></div><div><strong>${n}</strong><p>${t}</p></div></div>`).join('');
}
function baseOpenEvent(){if(state.finished||state.pending||!state.started)return;target=null;keys={};const m=missions[state.round];$('#eventLocation').textContent=locations[m.loc].name;$('#eventDay').textContent=`DAY ${state.round+1} / 16`;$('#eventType').textContent=m.type?'POWER MOVE · APPLY WHAT YOU LEARNED':'YOUR CALL';$('#eventTitle').textContent=m.title;$('#eventStory').textContent=m.story;$('#eventArt').innerHTML=sceneArt(m.loc);$('#choiceList').innerHTML=m.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span class="letter">${'ABC'[i]}</span><span><span class="ct">${esc(c.text)}</span><span class="fx">${c.delta.map((n,j)=>n?`${labels[j]} ${n>0?'+':''}${n}`:'').filter(Boolean).join(' · ')}</span></span></button>`).join('');$('#event').hidden=false;$('#choiceList button').focus();beep(440);}
function choose(i){if(choiceLocked||state.pending||state.finished)return;choiceLocked=true;if(state.round===0)unlock(0);if(state.round===1)unlock(1);const m=missions[state.round],c=m.choices[i];let d=apply(c.delta);const dayCost=(state.round+1)%4===0?3:0;if(dayCost){const cost=apply([-3,0,0,0]);d=d.map((n,i)=>n+cost[i]);}Object.assign(state.flags,c.flags);const correct=m.type?i===({2:2,3:0,4:1,5:0,6:2,7:0,8:1}[state.round]):null;if(correct)state.knowledge++;const item={day:state.round+1,title:m.title,choice:c.text,result:c.result,concept:c.concept,delta:d,stats:[...state.stats],correct};state.log.push(item);state.pending={...item,resultTitle:c.title,dayCost};save();$('#event').hidden=true;showResult();render();setTimeout(()=>choiceLocked=false,250);}
function showResult(){const p=state.pending;if(!p)return;$('#resultTitle').textContent=p.resultTitle;$('#resultText').textContent=p.result;$('#deltas').innerHTML=p.delta.map((n,i)=>`<div class="delta"><b class="${n<0?'negative':''}">${n>0?'+':''}${n}</b>${labels[i]}</div>`).join('');$('#learning').innerHTML=`<strong>${p.correct===true?'✓ POWER MOVE':'WHAT YOUR MOVE SHOWS'}</strong><br>${esc(p.concept)}${p.dayCost?'<br><span style="font-size:9px;opacity:.7">Includes −3 supplies for camp’s daily use.</span>':''}`;$('#continue').textContent=p.day===16?'See your island’s ending →':'Back to the island →';$('#result').hidden=false;$('#continue').focus();beep(p.correct===false?220:660,.15);}
function next(){if(!state.pending)return;state.activity={};state.round++;state.pending=null;$('#result').hidden=true;state.finished=state.round>=16;save();render();if(state.finished)showEnding();else{toast(`New mission: ${missions[state.round].title}`);if(state.stats.some(n=>n<=25))setTimeout(()=>toast('Camp is under pressure. Check your meters.'),2700)}}
function endingInfo(){const min=Math.min(...state.stats);if(state.failures.length)return ['COLLAPSE & SURVIVAL','Your camp made it through, but a system broke along the way. The island carries the consequences.','◈'];if(min>=60)return ['A COMMUNITY THAT HOLDS','You built a community that balances shared needs, safety, trust, and freedom.','✦'];if(min>=35)return ['FRAGILE PEACE','Your camp is still together. Some needs are secure; others need attention.','◇'];return ['ON THE EDGE','The community survived, but one more crisis could pull it apart.','△'];}
function showEnding(){const [title,desc,badge]=endingInfo();$('#endingTitle').textContent=title;$('#endingDesc').textContent=desc;$('#endingBadge').textContent=badge;$('#endingStats').innerHTML=state.stats.map((n,i)=>`<span><strong>${n}</strong>${labels[i]}</span>`).join('');$('#endingReview').innerHTML=`<p><strong>Government jobs completed:</strong> ${state.builds.length} / 8 blueprint steps.</p><p><strong>A choice that mattered:</strong> ${esc(state.log[9]?.choice||'Your first shared rule')}.</p><p><strong>Your government’s purpose:</strong> ${esc(state.log.at(-1)?.concept||'Organize shared needs.')}</p>`;$('#ending').hidden=false;beep(880,.3);}
function journal(){$('#journalTitle').textContent=state.finished?`${state.name}: final report`:'Your decisions';$('#journalEntries').innerHTML=state.log.length?state.log.map(l=>`<article class="log-entry"><span>DAY ${l.day}</span><h3>${esc(l.title)}</h3><p>You chose: ${esc(l.choice)}</p><p>${esc(l.result)}</p><small>${esc(l.concept)}</small></article>`).join(''):'<p>Your first decision is waiting at the water station.</p>';$('#journalDialog').showModal();}
function download(){const report={governmentBlueprint:state.builds,law:state.law,game:'Stranded — Government Day 1',island:state.name,completed:state.finished,missions:state.round,stats:Object.fromEntries(labels.map((n,i)=>[n,state.stats[i]])),appliedConceptsCorrect:state.knowledge,decisions:state.log};const blob=new Blob([`STRANDED — ISLAND REPORT\n${state.name}\n${state.finished?endingInfo()[0]:'In progress'}\nMissions resolved: ${state.round}/16\n${labels.map((n,i)=>`${n}: ${state.stats[i]}`).join(' | ')}\nGovernment blueprint: ${state.builds.length}/8\nYour law: ${state.law}\n\n${state.log.map(l=>`DAY ${l.day}: ${l.title}\nChoice: ${l.choice}\nResult: ${l.result}\nConnection: ${l.concept}\n${l.correct!==null?'Concept check: '+(l.correct?'Correct':'Review needed'):'Policy decision'}\n`).join('\n')}\nThis report records play on this device.\n`],{type:'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stranded-island-report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const canvas=$('#map'),ctx=canvas.getContext('2d');let vw=0,vh=0,dpr=1,scale=1,ox=0,oy=0,clock=0,lastTime=0;
const land=[ [152,464],[184,372],[267,304],[337,238],[420,225],[471,177],[564,195],[614,245],[711,230],[764,278],[808,362],[854,409],[860,492],[815,566],[808,643],[733,690],[687,753],[599,775],[537,812],[447,779],[368,794],[292,748],[236,683],[207,612],[166,560] ];
const cacheSpots=[{x:226,y:422},{x:370,y:290},{x:584,y:245},{x:773,y:400},{x:794,y:546},{x:718,y:668},{x:594,y:730},{x:433,y:734},{x:266,y:600},{x:565,y:505},{x:607,y:350},{x:385,y:465}];
function rand(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function polygon(points,fill){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill()}
function roundRect(x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill()}
function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function line(x1,y1,x2,y2,c,w=1){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function inside(x,y){let c=false;for(let i=0,j=land.length-1;i<land.length;j=i++){const a=land[i],b=land[j];if(((a[1]>y)!=(b[1]>y))&&(x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]))c=!c}return c}
function palm(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ellipse(6,9,21,7,'#0c3c3544');ctx.strokeStyle='#92724d';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(0,5);ctx.quadraticCurveTo(5,-20,-1,-38);ctx.stroke();const sway=Math.sin(clock*.6+x)*2;for(let i=0;i<6;i++){const a=i*Math.PI/3+sway*.02;const dx=Math.cos(a)*29,dy=Math.sin(a)*15;ctx.beginPath();ctx.moveTo(-1,-37);ctx.quadraticCurveTo(dx*.4,-56+dy,dx,-36+dy);ctx.quadraticCurveTo(dx*.5,-35+dy,-1,-37);ctx.fillStyle=i%2?'#2c7354':'#42895d';ctx.fill()}ctx.restore()}
function tent(x,y,s=1,c='#c59b61'){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ellipse(4,11,30,10,'#163e3444');polygon([[-27,7],[0,-29],[28,7]],c);polygon([[0,-29],[28,7],[43,-2],[17,-35]],'#92754c');polygon([[-12,7],[0,-14],[12,7]],'#163c3c');line(0,-29,0,7,'#e6c58c',1);line(-27,7,-36,15,'#8a7652');line(28,7,34,15,'#8a7652');ctx.restore()}
function crate(x,y,glow=false){if(glow){ellipse(x,y+7,20,10,'#91d2ae18');ctx.strokeStyle=`rgba(149,224,182,${.2+.2*Math.sin(clock*3)})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,18+Math.sin(clock*3)*3,12+Math.sin(clock*3)*2,0,0,7);ctx.stroke()}roundRect(x-9,y-8,18,18,2,'#a67a46');polygon([[x-9,y-8],[x-4,y-12],[x+13,y-12],[x+9,y-8]],'#d5b16b');polygon([[x+9,y-8],[x+13,y-12],[x+13,y+5],[x+9,y+10]],'#785d39');line(x-6,y-5,x+6,y+6,'#d8b97c',2);line(x+6,y-5,x-6,y+6,'#d8b97c',2);if(glow){ctx.fillStyle='#b4f3bd';ctx.font='bold 13px Arial';ctx.textAlign='center';ctx.fillText('+',x,y-18)}}
function person(x,y,c='#bca278',size=1,walk=false){ctx.save();ctx.translate(x,y);ctx.scale(size,size);ellipse(2,7,10,4,'#0a292b55');const step=walk?Math.sin(clock*12)*3:0;line(-3,3,-3-step,9,'#183b43',3);line(3,3,3+step,9,'#183b43',3);roundRect(-6,-7,12,14,4,c);ellipse(0,-10,5,6,'#dbb48b');ellipse(0,-13,5,2.5,'#453c2e');ctx.restore()}
